uniform float defaultOpacity;
uniform float luminosityThreshold;
uniform float smoothWidth;

varying vec2 vUv;

void main() {

	vec4 texel = texture2D( tDiffuse, vUv );

	float v = luminance( texel.xyz );

	vec4 outputColor = vec4( defaultColor.rgb, defaultOpacity );

	float alpha = smoothstep( luminosityThreshold, luminosityThreshold + smoothWidth, v );

	gl_FragColor = mix( outputColor, texel, alpha );

}

look_Mc.fragmentShader:
uniform sampler2D tDiffuse;
uniform vec2 uLight;
uniform float uStrength;
uniform int uSamples;
uniform float uAspect;
varying vec2 vUv;
float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
void main() {
  vec4 base = texture2D(tDiffuse, vUv);
  if (uStrength <= 0.001) { gl_FragColor = vec4(base.rgb, 1.0); return; }
  vec2 delta = (vUv - uLight) / float(uSamples) * 0.92;
  vec2 uv = vUv - delta * hash(vUv * 731.0);
  float decay = 1.0;
  vec3 acc = vec3(0.0);
  for (int i = 0; i < 96; i++) {
    if (i >= uSamples) break;
    uv -= delta;
    vec4 s = texture2D(tDiffuse, clamp(uv, 0.0, 1.0));
    acc += s.rgb * s.a * decay;
    decay *= 0.965;
  }
  acc /= float(uSamples);

  vec2 toL = (vUv - uLight) * vec2(uAspect, 1.0);
  float falloff = exp(-dot(toL, toL) * 6.0);
  gl_FragColor = vec4(base.rgb + acc * uStrength * 2.2 * falloff, 1.0);
}

look_Pc.fragmentShader:
uniform sampler2D tDiffuse;
uniform float uTime;
uniform vec2 uRes;
uniform float uExposure;
uniform float uLift;
uniform float uGain;
uniform vec3 uShadowTint;
uniform vec3 uHighTint;
uniform float uSat;
uniform float uDarkDesat;
uniform float uContrast;
uniform float uVignette;
uniform float uGrain;
uniform float uPaper;
uniform float uHighK;
uniform float uSplitK;
uniform float uDarkTintK;
varying vec2 vUv;
float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p) {
  vec2 i = floor(p); vec2 f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1, 0)), f.x), mix(hash(i + vec2(0, 1)), hash(i + vec2(1, 1)), f.x), f.y);
}
void main() {
  vec3 c = texture2D(tDiffuse, vUv).rgb * uExposure;
  float l = dot(c, vec3(0.2126, 0.7152, 0.0722));

  float sat = mix(0.35, 1.15, uSat) * (1.0 - uDarkDesat * (1.0 - smoothstep(0.02, 0.25, l)));
  c = mix(vec3(l), c, sat);

  float sh = 1.0 - smoothstep(0.0, 0.18, l);
  float hi = smoothstep(0.25, 1.2, l);
  c = mix(c, c * 0.6 + uShadowTint * 0.5, sh * 0.35 * uSplitK);
  c = mix(c, c * uHighTint * 1.15, hi * 0.35 * uHighK);

  float k = mix(0.85, 1.25, uContrast);
  c = pow(max(c, vec3(1e-5)) / 0.18, vec3(k)) * 0.18;

  c = c * uGain + uLift * 0.25 * (1.0 - c / (1.0 + c));

  if (uPaper > 0.001) {
    float p = vnoise(vUv * uRes / 3.0) * 0.5 + vnoise(vUv * uRes / 11.0) * 0.35 + vnoise(vUv * uRes / 40.0) * 0.15;
    c *= 1.0 + (p - 0.5) * 0.22 * uPaper;
    c = mix(c, c + vec3(0.03, 0.028, 0.022), uPaper * 0.6);
  }

  float lw0 = dot(c, vec3(0.2126, 0.7152, 0.0722));
  float darkK = 1.0 - smoothstep(0.03, 0.13, lw0);

  vec3 tintN = uShadowTint / max(dot(uShadowTint, vec3(0.2126, 0.7152, 0.0722)), 1e-4);

  vec3 tintD = mix(vec3(1.0), tintN, 0.05) * vec3(1.03, 0.97, 1.08);
  c = mix(c, lw0 * tintD, darkK * 0.55 * uDarkTintK);

  vec2 q = vUv - 0.5;
  q.x *= uRes.x / uRes.y * 0.75;
  float v = (1.0 - smoothstep(0.2, 0.85, length(q)));
  c *= mix(1.0, v, uVignette * 1.4);

  float g = hash(vUv * uRes + fract(uTime * 13.7) * 100.0) - 0.5;
  float lw = smoothstep(0.0, 0.08, l) * (1.0 - smoothstep(0.6, 2.0, l));
  c += c * g * uGrain * 4.0 * lw + g * uGrain * 0.03;

  c += (hash(vUv * uRes + 17.0) - 0.5) / 255.0;
  gl_FragColor = vec4(max(c, vec3(0.0)), 1.0);
}

look_Fc.fragmentShader:
uniform sampler2D tDiffuse;
uniform float uToe;
varying vec2 vUv;
vec3 neutral(vec3 color) {
  const float StartCompression = 0.8 - 0.04;
  const float Desaturation = 0.15;
  float x = min(color.r, min(color.g, color.b));
  float offset = x < 0.08 ? x - 6.25 * x * x : 0.04;
  offset *= mix(smoothstep(0.05, 0.25, x), 1.0, uToe);
  color -= offset;
  float peak = max(color.r, max(color.g, color.b));
  if (peak < StartCompression) return color;
  float d = 1.0 - StartCompression;
  float newPeak = 1.0 - d * d / (peak + d - StartCompression);
  color *= newPeak / peak;
  float g = 1.0 - 1.0 / (Desaturation * (peak - newPeak) + 1.0);
  return mix(color, vec3(newPeak), g);
}
vec3 toSrgb(vec3 c) {
  return mix(c * 12.92, 1.055 * pow(max(c, vec3(1e-6)), vec3(1.0 / 2.4)) - 0.055, step(vec3(0.0031308), c));
}
void main() {
  gl_FragColor = vec4(toSrgb(clamp(neutral(texture2D(tDiffuse, vUv).rgb), 0.0, 1.0)), 1.0);
}

